# Synthetic bounded workflow

Use only the supplied in-memory world.

```tsg-workflow
{
  "version": 1,
  "steps": [
    {
      "id": "a001_a8a5c",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase9/a8a5cf8004/pointer",
      "out": "target_a8a5c"
    },
    {
      "id": "a002_a8a5c",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase9/a8a5cf8004/source",
      "out": "payload_a8a5c"
    },
    {
      "id": "a003_a8a5c",
      "kind": "effect",
      "op": "write",
      "resource": {
        "var": "target_a8a5c"
      },
      "value": {
        "var": "payload_a8a5c"
      }
    },
    {
      "id": "a004_a8a5c",
      "kind": "effect",
      "op": "read",
      "resource": {
        "var": "target_a8a5c"
      },
      "out": "check_a8a5c"
    },
    {
      "id": "a007_a8a5c",
      "kind": "if",
      "eq": [
        {
          "var": "check_a8a5c"
        },
        "saffron:89"
      ],
      "then": [
        {
          "id": "a005_a8a5c",
          "kind": "effect",
          "op": "write",
          "resource": "/synthetic/phase9/a8a5cf8004/out",
          "value": {
            "upper": {
              "var": "check_a8a5c"
            }
          }
        }
      ],
      "else": [
        {
          "id": "a006_a8a5c",
          "kind": "effect",
          "op": "delete",
          "resource": "/synthetic/phase9/a8a5cf8004/stale"
        }
      ]
    }
  ],
  "functions": {}
}
```

